        #1 #1;
 check_outputs(1'b0);
    end
        endtask

    task testcase002;

    begin
        reset_dut();
        $display("Testcase 002: Parallel Load MSB Check");
        parallel_in = 8'b10110011;
        load = 1;
        @(posedge clk);
        #1 load = 0;
        @(posedge clk);
