        reset_dut();
        $display("Testcase 003: Shift Check (Bit 6)");
        parallel_in = 8'b01000000;
        load = 1;
        @(posedge clk);
        #1 load = 0;
        @(posedge clk);
        @(posedge clk);
        #1 #1;
 check_outputs(1'b1);
    end
        endtask

    task testcase004;

    begin
        reset_dut();
        $display("Testcase 004: Full Shift Check (LSB)");
        parallel_in = 8'b00000001;
        load = 1;
        @(posedge clk);
        #1 load = 0;
        repeat(8) @(posedge clk);
        #1 #1;
 check_outputs(1'b1);
    end
        endtask

    task testcase005;

    begin
        reset_dut();
        $display("Testcase 005: All Zeros Check");
        parallel_in = 8'h00;
        load = 1;
        @(posedge clk);
        #1 load = 0;
        @(posedge clk);
        #1 #1;
 check_outputs(1'b0);
    end
        endtask

    task testcase006;

    begin
        reset_dut();
        $display("Testcase 006: Load Priority Check");
        parallel_in = 8'hAA;
