    w1,
    w1024,
    w1023,
    w8,
    w9,
    w144,
    w1167,
    w4668,
    w3501,
    w7002;

  assign w1 = i_data0;
  assign w1023 = w1024 - w1;
  assign w1024 = w1 << 10;
  assign w1167 = w1023 + w144;
  assign w144 = w9 << 4;
  assign w3501 = w4668 - w1167;
  assign w4668 = w1167 << 2;
  assign w7002 = w3501 << 1;
  assign w8 = w1 << 3;
  assign w9 = w1 + w8;

  assign o_data0 = w7002;


endmodule

