module top_module(
  input [2:0] sel,
  input [3:0] data0,
  input [3:0] data1,
  input [3:0] data2,
  input [3:0] data3,
  input [3:0] data4,
  input [3:0] data5,
  output reg [3:0] out
);wire [5:0] sel_decoded;
  assign sel_decoded = {~sel[2] & ~sel[1] & ~sel[0], ~sel[2] & ~sel[1] & sel[0], ~sel[2] & sel[1] & ~sel[0], ~sel[2] & sel[1] & sel[0], sel[2] & ~sel[1] & ~sel[0], sel[2] & ~sel[1] & sel[0]};

