description:
Create a simple toggle circuit that controls an LED based on a button press. The module detects the rising edge of a button (BTN1) and toggles the state of the LED (LED1) whenever the button is pressed, changing the LED's state from ON to OFF or vice versa. The output LED is driven by a registered state that ensures the toggle occurs only once per button press.
module top_module(
    input CLK,
    input BTN1,
    output LED1
);

code:
module top_module(
    input CLK,
    input BTN1,
    output LED1
);reg r_LED1 = 1'b0;
reg r_BTN1 = 1'b0;

always @(posedge CLK) begin
    r_BTN1 <= BTN1;

    if (BTN1 == 1'b0 && r_BTN1 == 1'b1)
    begin
        r_LED1 <= ~r_LED1;
    end
end

    assign LED1 = r_LED1;

endmodule

