description:
Design a synchronous random access memory (SRAM) module with configurable word and address widths. The module features a clock input, a write enable signal, and an enable signal to control read/write operations. When enabled, if the write enable signal is asserted, data from the input (`din`) is stored in the memory at the specified address; simultaneously, this data is also output to `dout`. If the write enable signal is not asserted, the data at the specified address is read from the memory and presented at the output. This allows for selective reading and writing of data in a memory array.
module top_module(

   dout,

   clk, we, en, addr, din
   );

code:
module top_module(

   dout,

   clk, we, en, addr, din
   );parameter WORD_WIDTH = 16;
   parameter ADDR_WIDTH = 10;


   input clk;
   input we;
   input en;
   input [9:0] addr;
   input [WORD_WIDTH-1:0] din;
   output [WORD_WIDTH-1:0] dout;
   reg [WORD_WIDTH-1:0]    RAM [(2<<ADDR_WIDTH)-1:0];
   reg [WORD_WIDTH-1:0]    dout;

   always @(posedge clk)
     begin
        if (en)
          begin
             if (we)
               begin
                  RAM[addr] <= din;
                  dout <= din;
               end
             else begin
               dout <= RAM[addr];

             end
          end
     end
endmodule

