description:
Design a clock generator that produces a 100 Hz output signal (clk_100) based on a primary clock input (clk) of 200 kHz. This module includes a reset input (rst_n) to initialize the output and internal counters. It uses an 18-bit counter to track 200,000 clock cycles, toggling the clk_100 output every time the count reaches 199,999, effectively dividing the input frequency by 2000 to achieve the desired output frequency.
module top_module(
  clk,
  rst_n,
  clk_100
);

code:
module top_module(
  clk,
  rst_n,
  clk_100
);input clk;
input rst_n;
output clk_100;

reg clk_100;
reg clk_100_next;
reg [17:0] count_200K;
reg [17:0] count_200K_next;

always @*
  if (count_200K == 199_999)
  begin
    count_200K_next = 18'd0;
	 clk_100_next = ~clk_100;
  end
  else
  begin
    count_200K_next = count_200K + 1'b1;
	 clk_100_next = clk_100;
  end

always @(posedge clk or negedge rst_n)
  if (~rst_n)
  begin
    count_200K <= 18'd0;
    clk_100 <= 1'b0;
  end
  else
  begin
    count_200K <= count_200K_next;
    clk_100 <= clk_100_next;
  end

endmodule

